const run = a.variant("checked"); const row = run.function("row"); const middle = row.timeline("middle");
const hdr = q.ir.instructions().opcode("load").resultType("i32").pointer(row.argument(0)).count();
const tl = q.run(middle.select("ordinal","pass","scope","ref"));
const ch = q.run(middle.measure(hdr).changes().table("ordinal","pass","before","after","delta","status"));
({arg0: q.run(row.argument(0)), metric: q.run(hdr), timelineLen: tl.length, changesLen: ch.length, first10: ch.slice(0,10), stat: q.run(hdr).unit})

const probe = {};
try { probe.arg0raw = row.argument(0); } catch(e){ probe.arg0raw = String(e); }
try { probe.metricraw = hdr; } catch(e){ probe.metricraw = String(e); }
try { probe.tlLen = q.run(middle.select("ordinal","pass")).length; } catch(e){ probe.tlErr = String(e); }
probe

const chRes = q.run(middle.measure(hdr).changes().table("ordinal","pass","fromPass","before","after","delta","status"));
const rows = chRes.rows;
({of: chRes.of, unit: chRes.unit, n: rows.length,
 negKnown: rows.filter(r=>r.status==="known"&&r.delta<0),
 statusTally: rows.reduce((m,r)=>(m[r.status]=(m[r.status]||0)+1,m),{})})

const v73 = q.run(hdr.at(middle.at(73).after));
const v74 = q.run(hdr.at(middle.at(74).after));
const gapDemo = q.run(middle.where(e=>e.pass==="EarlyCSEPass").measure(hdr).changes().table("ordinal","pass","before","after","delta","status","skipped","endpointDelta"));
const locs = q.run(run.initialModule().sourceLocations({ function: "row" }));
const scopes = q.run(middle.select("ordinal","pass","scope"));
({v73, v74, gapDemo, locs,
 scopeKinds: scopes.rows.reduce((m,r)=>(m[r.scope&&r.scope.kind]=(m[r.scope&&r.scope.kind]||0)+1,m),{})})

const meas = q.run(middle.measure(hdr).table("ordinal","pass","status","value","reason"));
const statusTally = meas.rows.reduce((m,r)=>(m[(r.status||"null")+(r.reason?"/"+r.reason:"")]=(m[(r.status||"null")+(r.reason?"/"+r.reason:"")]||0)+1,m),{});
const loopEv = q.run(run.events("middle").where(e=>e.scope && e.scope.kind==="loop").first());
let loopProbe = null;
try { loopProbe = q.run(hdr.at(loopEv.after)); } catch(e) { loopProbe = {err:String(e)}; }
({statusTally, nMeas: meas.rows.length, loopEv: loopEv && {ordinal:loopEv.ordinal, pass:loopEv.pass, scope:loopEv.scope},
  loopProbe: loopProbe && {status:loopProbe.status, reason:loopProbe.reason, value:loopProbe.value, coverage:loopProbe.state&&loopProbe.state.coverage}})

const le = q.run(run.events("middle").where(e=>e.scope && e.scope.kind==="loop").first());
const leRow = (le.rows && le.rows[0]) || le;
let lp;
try { lp = q.run(hdr.at(leRow.after)); } catch(e){ lp = {err:String(e)}; }
({leKeys: Object.keys(le), kind: le.kind, of: le.of, leRow: leRow && {ordinal:leRow.ordinal, pass:leRow.pass, scope:leRow.scope, header:leRow.header},
  lp: lp && {status:lp.status, reason:lp.reason, value:lp.value, coverage:lp.state&&lp.state.coverage, fix:lp.fix}})

const le2 = q.run(run.events("middle").where(e=>e.scope && e.scope.kind==="loop").first());
const allEv = q.run(run.events("middle").select("ordinal","pass","scope"));
const scopeTally = allEv.rows.reduce((m,r)=>(m[r.scope&&r.scope.kind]=(m[r.scope&&r.scope.kind]||0)+1,m),{});
const modEvs = allEv.rows.filter(r=>r.scope && r.scope.kind==="module");
const modProbe = modEvs.slice(0,6).map(r=>{ try { const x=q.run(hdr.at(q.run(run.events("middle").at(r.ordinal)).after)); return {ordinal:r.ordinal,pass:r.pass,status:x.status,reason:x.reason,value:x.value}; } catch(e){ return {ordinal:r.ordinal,err:String(e).slice(0,80)}; } });
({leStatus: le2.status, leCount: le2.count, totalMiddle: allEv.rows.length, scopeTally, modProbe})

const w73 = v73.witnesses.map(w=>w.line+"|"+w.block), w74 = v74.witnesses.map(w=>w.line+"|"+w.block);
const goneAt74 = w73.filter(x=>!w74.includes(x));
const locsFull = q.run(run.initialModule().sourceLocations({ function: "row" }));
let capsFiltered = null;
try { const c = q.capabilities(); const arr = Array.isArray(c)? c : (c.rows || c.capabilities || []);
  capsFiltered = arr.filter(x=>/source|debug|locat|remark|pc/i.test(JSON.stringify(x))).map(x=>({name:x.name||x.id||x.capability, status:x.status, call:(x.call||x.how||"").slice(0,90)}));
} catch(e){ capsFiltered = String(e).slice(0,100); }
({destroyed: goneAt74, n73: w73.length, n74: w74.length,
  why: locsFull.why, checked: locsFull.checked, capsFiltered})
